# Sales Data Analysis System
# Objectives:
# - Calculate the amount of revenue generated by the business
# - Identify for the product which sold the most
# - Identify for the products which generated the highest profit
# - Identify the date with the highest sales

import pandas as pd
import numpy as np

df = pd.read_csv("salesdata.csv")

df = df.drop_duplicates()
df = df.dropna(
    subset= ["Quantity", "UnitPrice", "UnitCost"]
)

print("=================== Sales Data ===================")
df["Revenue"] = df["UnitPrice"].to_numpy() * df["Quantity"].to_numpy()
df["TotalCost"] = df["UnitCost"].to_numpy() * df["Quantity"].to_numpy()
df["Profit"] = df["Revenue"] - df["TotalCost"]

total_revenue = np.sum(df["Revenue"].to_numpy())
total_profit = np.sum(df["Profit"].to_numpy())
total_cost = np.sum(df["TotalCost"].to_numpy())
total_quantity = np.sum(df["Quantity"].to_numpy())
average_sale = np.mean(df["Revenue"].to_numpy())
standard_deviation = np.std(df["Revenue"].to_numpy()).round(2)
product_quantity = df.groupby("Product")["Quantity"].sum().sort_values(ascending= False)
product_revenue = df.groupby("Product")["Revenue"].sum().sort_values(ascending=False)
date_revenue = df.groupby("Date")["Revenue"].sum().sort_values(ascending=False)
product_analysis = df.groupby("Product")["Revenue"].sum().agg(["mean", "std", "max", "min", "count"]).round(2)


print(f"""
{df}

=================== Product_Quantity ===================
{product_quantity}
----------- The product wich sold most units: {product_quantity.idxmax()}

=================== Product_Revenue ===================
{product_revenue}
---------- The product is generated the highest revenue: {product_revenue.idxmax()}

=================== Date_Revenue ===================
{date_revenue}
---------- The date with the highest revenue: {date_revenue.idxmax()}

=================== Product_Analysis ===================
{product_analysis}

Total Revenue: {total_revenue}
Average Sale per Transaction: {average_sale}
Total Profit: {total_profit}
Total Cost: {total_cost}
Total Quantity: {total_quantity}
Standard deviation: {standard_deviation}
      """)